item.command:
/bin/zsh -lc 'bun test
build_dir=$(mktemp -d /tmp/dependency-planner-build.XXXXXX)
bun build src/cli.ts --target=bun --outdir "$build_dir"
bun -e '"'
import { createPlan } from \"./src/cli.ts\";
for (let run = 0; run < 500; run++) {
  const n = Math.floor(Math.random() * 15);
  const tasks = Array.from({length:n}, (_, i) => ({ id: "'`t${String(i).padStart(2,"0")}`, duration: Math.floor(Math.random()*5), dependsOn: [] as string[] }));
  for (let i=0;i<n;i++) for (let j=0;j<i;j++) if (Math.random()<0.18) tasks[i].dependsOn.push(tasks[j].id);
  tasks.sort(() => Math.random() - 0.5);
  const plan = createPlan({tasks});
  const position = new Map(plan.order.map((id,i)=>[id,i]));
  const layer = new Map(plan.layers.flatMap((ids,i)=>ids.map(id=>[id,i] as const)));
  for (const task of tasks) for (const dep of task.dependsOn) {
    if (!(position.get(dep)! < position.get(task.id)!)) throw new Error("invalid order");
    if (!(layer.get(dep)! < layer.get(task.id)!)) throw new Error("invalid layer");
  }
  let sum = 0;
  for (let i=0;i<plan.criticalPath.length;i++) {
    const task = tasks.find(t=>t.id===plan.criticalPath[i])!;
    sum += task.duration;
    if (i && !task.dependsOn.includes(plan.criticalPath[i-1])) throw new Error("invalid critical edge");
  }
  if (sum !== plan.totalDuration) throw new Error(`critical sum ${sum} != ${plan.totalDuration}`);
}
console.log("randomized invariants: 500 passed");
'"'
git diff --check
git status --short
git diff --stat"

